use maho_ext_pi_websearch::websearch::{search::*,types::*};
fn providers(value:serde_json::Value)->Vec<SearchProviderEntry>{serde_json::from_value(value).expect("provider fixtures")}
#[test]fn weighted_round_robin_rotates_unique_routes(){let providers=providers(serde_json::json!([{"provider":"exa","weight":2},{"provider":"tavily","weight":1}]));let mut state=create_search_routing_state(2);let routes=(0..3).map(|_|select_order(RoutingStrategy::RoundRobin,&providers,&mut state)).collect::<Vec<_>>();assert_eq!(routes,vec![vec![0,1],vec![0,1],vec![1,0]]);}
#[test]fn priority_ties_preserve_source_order(){let providers=providers(serde_json::json!([{"provider":"exa","priority":2},{"provider":"tavily","priority":0},{"provider":"brave","priority":0}]));assert_eq!(select_order(RoutingStrategy::Priority,&providers,&mut create_search_routing_state(3)),vec![1,2,0]);}
#[test]fn fill_first_prefers_least_successful(){let providers=providers(serde_json::json!([{"provider":"exa"},{"provider":"tavily"},{"provider":"brave"}]));let mut state=SearchRoutingState{round_robin_cursor:0,success_counts:vec![3.0,1.0,1.0]};assert_eq!(select_order(RoutingStrategy::FillFirst,&providers,&mut state),vec![1,0,2]);}
#[test]fn native_entry_labels_hide_generated_suffix(){assert_eq!(provider_entry_label("exa",Some("custom"),Some("native-exa-model")),"exa/native");assert_eq!(provider_entry_label("exa",Some("custom"),Some("")),"exa");}
